INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Arbeite ich hier ohne Spezifikationen?', 2, '[{"text": "Nein", "correct": true, "because": "Spezifikationen sind Basis"}, {"text": "Ja", "correct": false, "because": "Dokumentation zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dokumentation definiert die Anforderungen?', 3, '[{"text": "Spezifikationen", "correct": true, "because": "Anforderungen festlegen"}, {"text": "Abnahmeprotokolle", "correct": false, "because": "Abschlussdokument"}, {"text": "Testpläne", "correct": false, "because": "Teststrategie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterlagen gehören zur Dokumentation?', 5, '[{"text": "Spezifikationen", "correct": true, "because": "Anforderungen definieren"}, {"text": "Testpläne", "correct": true, "because": "Tests planen"}, {"text": "Unstrukturierte Notizen", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Abnahmeprotokolle validieren das System. b) Testpläne sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Testpläne essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei dieser Dokumentation?', 4, '[{"text": "Spezifikationen", "correct": false, "because": "Grundlage des Projekts"}, {"text": "Abnahmeprotokolle", "correct": false, "because": "Abschluss validieren"}, {"text": "Ungeplante Änderungen", "correct": true, "because": "Nachvollziehbarkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier ohne Testpläne arbeite?', 2, '[{"text": "Nein", "correct": true, "because": "Testpläne sind Kern"}, {"text": "Ja", "correct": false, "because": "Qualitätssicherung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dokumentation wähle ich für den Projektabschluss?', 3, '[{"text": "Abnahmeprotokolle", "correct": true, "because": "Systemvalidierung"}, {"text": "Spezifikationen", "correct": false, "because": "Anforderungen definieren"}, {"text": "Testpläne", "correct": false, "because": "Teststrategie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterlagen fördern Nachvollziehbarkeit?', 5, '[{"text": "Spezifikationen", "correct": true, "because": "Anforderungen dokumentieren"}, {"text": "Abnahmeprotokolle", "correct": true, "because": "Validierung festhalten"}, {"text": "Zufällige Skizzen", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Testpläne sichern Qualität. b) Spezifikationen sind unwichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Spezifikationen essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Testpläne", "correct": false, "because": "Qualität prüfen"}, {"text": "Spezifikationen", "correct": false, "because": "Basis des Projekts"}, {"text": "Unstrukturierte Daten", "correct": true, "because": "Struktur zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Abnahmeprotokolle hier unwichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Validierung abschließen"}, {"text": "Ja", "correct": false, "because": "Abnahme zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dokumente unterstützen die Qualitätssicherung?', 4, '[{"text": "Testpläne", "correct": true, "because": "Tests strukturieren"}, {"text": "Abnahmeprotokolle", "correct": true, "because": "System prüfen"}, {"text": "Lose Notizen", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich hier ohne Spezifikationen arbeite. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Spezifikationen sind Basis"}, {"text": "Ja", "correct": false, "because": "Dokumentation zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich zu Projektbeginn?', 3, '[{"text": "Spezifikationen", "correct": true, "because": "Anforderungen festlegen"}, {"text": "Abnahmeprotokolle", "correct": false, "because": "Abschlussdokument"}, {"text": "Testpläne", "correct": false, "because": "Später im Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Testpläne planen Tests. b) Abnahmeprotokolle sind nebensächlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abnahmeprotokolle wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat diese Dokumentation?', 5, '[{"text": "Nachvollziehbarkeit", "correct": true, "because": "Alles dokumentiert"}, {"text": "Qualitätssicherung", "correct": true, "because": "Tests und Abnahme"}, {"text": "Unstrukturierte Arbeit", "correct": false, "because": "Struktur zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Spezifikationen", "correct": false, "because": "Basis des Projekts"}, {"text": "Testpläne", "correct": false, "because": "Qualität sichern"}, {"text": "Ungeplante Änderungen", "correct": true, "because": "Dokumentation zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Testpläne hier unwichtig?', 3, '[{"text": "Nein", "correct": true, "because": "Tests strukturieren"}, {"text": "Ja", "correct": false, "because": "Qualitätssicherung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier ohne Abnahmeprotokolle arbeite?', 2, '[{"text": "Nein", "correct": true, "because": "Abnahmeprotokolle sind Kern"}, {"text": "Ja", "correct": false, "because": "Validierung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dokumentation wähle ich für Tests?', 4, '[{"text": "Testpläne", "correct": true, "because": "Teststrategie definieren"}, {"text": "Abnahmeprotokolle", "correct": false, "because": "Abschlussdokument"}, {"text": "Unstrukturierte Ideen", "correct": false, "because": "Struktur nötig"}]');
